// Regenerates src/components/ui/iconPaths.ts from @material-symbols/svg-400 (Material Symbols
// Rounded, weight 400 - the house icon set, Part 13 D-20). The site inlines only the few glyphs
// it uses, as path data, instead of loading the 3.96 MB icon font (ProblemSection's old note) or
// adding an SVG loader. Add a name below, run `npm run icons`, and commit the generated file.
import { readFileSync, writeFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { dirname, join } from 'node:path';

// Glyph names as Material Symbols spells them; "-fill" is the filled variant.
const NAMES = [
  'account_balance_wallet',
  'arrow_forward',
  'chat',
  'check_circle',
  'close',
  'credit_card',
  'eco',
  'help',
  'mail',
  'menu',
  'play_arrow-fill',
  'receipt_long',
  'schedule',
  'sync',
  'volume_off',
];

const require = createRequire(import.meta.url);
const root = dirname(require.resolve('@material-symbols/svg-400/package.json'));
const { version } = JSON.parse(readFileSync(join(root, 'package.json'), 'utf8'));

const entries = NAMES.map((name) => {
  const svg = readFileSync(join(root, 'rounded', `${name}.svg`), 'utf8');
  if (!svg.includes('viewBox="0 -960 960 960"')) throw new Error(`${name}: unexpected viewBox`);
  const paths = [...svg.matchAll(/<path d="([^"]+)"/g)].map((m) => m[1]);
  if (paths.length !== 1) throw new Error(`${name}: expected one <path>, found ${paths.length}`);
  return `  '${name}': '${paths[0]}',`;
});

const out = `// GENERATED by scripts/icons.mjs from @material-symbols/svg-400@${version} (Rounded, weight 400).
// Do not edit by hand: add the name to the script and run \`npm run icons\`.
export const ICON_PATHS = {
${entries.join('\n')}
} as const;

export type IconName = keyof typeof ICON_PATHS;
`;
writeFileSync(new URL('../src/components/ui/iconPaths.ts', import.meta.url), out);
console.log(`wrote ${NAMES.length} icons from @material-symbols/svg-400@${version}`);
